#!/usr/bin/env node
'use strict';
/*
 * catalog.js - writes references/catalog.md, the list of every name a scenario may use.
 *
 *   node catalog.js
 *
 * The file is generated from the runtime itself (Pres.catalog(), Pres.emoteCatalog(), Character.actions
 * and the sound catalog), so it always matches the engine. Do not edit it by hand: run this script again.
 */
const fs = require('fs');
const path = require('path');
const { createRuntime } = require('./lib/load-runtime');

const OUT = path.join(__dirname, '..', 'references', 'catalog.md');

const cell = (v) => String(v === undefined || v === null ? '' : v).replace(/\|/g, '\\|').replace(/\r?\n/g, ' ');

// A Markdown table from a header row and rows of values.
function table(headers, rows) {
  const line = (cells) => `| ${cells.map(cell).join(' | ')} |`;
  return [line(headers), line(headers.map(() => '---')), ...rows.map(line)].join('\n');
}

// A one-column table of plain names.
const names = (header, list) => table([header], list.map((x) => [x]));

function build(rt) {
  const { Pres, window: win } = rt;
  const cat = Pres.catalog();
  const emotes = Pres.emoteCatalog();
  const actions = win.Character.actions;

  const out = [];
  out.push('# Catalog (generated, do not edit by hand)');
  out.push('');
  out.push('Generated by `node scripts/catalog.js` from the engine. The AI must only use names from this file:');
  out.push('any other name is a validation error. Stage: 240 x 135 pixels. Run `node scripts/validate.js <file>`');
  out.push('to check a scenario.');
  out.push('');

  out.push('## Backgrounds');
  out.push('');
  out.push(table(['id', 'label', 'tone', 'ground'],
    cat.backgrounds.map((b) => [b.id, b.label, b.tone, b.ground])));
  out.push('');

  out.push('## Props');
  out.push('');
  out.push(table(['id', 'label', 'w x h'],
    cat.props.map((p) => [p.id, p.label, `${p.w} x ${p.h}`])));
  out.push('');

  out.push('## Skins');
  out.push('');
  out.push(names('skin', cat.skins));
  out.push('');

  out.push('## Expressions');
  out.push('');
  out.push(names('expression', cat.expressions));
  out.push('');

  out.push('## Poses');
  out.push('');
  out.push(names('pose', cat.poses));
  out.push('');

  out.push('## Positions');
  out.push('');
  out.push(names('position', cat.positions));
  out.push('');

  out.push('## Prop enters');
  out.push('');
  out.push(names('enter', cat.enters));
  out.push('');

  out.push('## Character enters');
  out.push('');
  out.push(names('enter', cat.charEnters));
  out.push('');

  out.push('## Character exits');
  out.push('');
  out.push(names('exit', cat.charExits));
  out.push('');

  out.push('## Gazes');
  out.push('');
  out.push(names('gaze', cat.gazes));
  out.push('');

  out.push('## Transitions');
  out.push('');
  out.push(names('transition', cat.transitions));
  out.push('');

  out.push('## Camera focus');
  out.push('');
  out.push(names('focus', cat.cameraFocus));
  out.push('');
  out.push('Also `prop:<id>` (a prop on the slide) and `[x, y]` (stage pixels).');
  out.push('');

  out.push('## Camera moves');
  out.push('');
  out.push(names('move', cat.cameraMoves));
  out.push('');

  out.push('## Camera zoom');
  out.push('');
  out.push(names('zoom', cat.zooms));
  out.push('');

  out.push('## Emotes');
  out.push('');
  out.push(table(['id', 'label'], emotes.map((e) => [e.id, e.label])));
  out.push('');

  out.push('## Character actions');
  out.push('');
  out.push(names('action', actions));
  out.push('');

  out.push('## Music moods');
  out.push('');
  out.push(table(['id', 'label', 'bpm'], cat.music.map((m) => [m.id, m.label, m.bpm])));
  out.push('');
  out.push('A slide\'s `music` may also be `"none"`, which stops the loop from that slide on.');
  out.push('');

  out.push('## Sound effects');
  out.push('');
  out.push(table(['id', 'label'], cat.sfx.map((s) => [s.id, s.label])));
  out.push('');

  return out.join('\n');
}

function main() {
  const text = build(createRuntime());
  fs.writeFileSync(OUT, text, 'utf8');
  console.log(`wrote ${OUT}`);
  return 0;
}

process.exitCode = main();
